FEEDBACK_WRITER_INPUT_V1:
{
  "contract": "FEEDBACK_WRITER_INPUT_V1",
  "effectClaimMode": "POTENTIAL_ONLY",
  "interactionLabel": "24/09/2026",
  "uncertainty": "evidência de uma única interação; não representa padrão",
  "constraints": [
    {
      "code": "ONLY_THIS_INTERACTION",
      "text": "Fale somente sobre esta interação."
    },
    {
      "code": "NEVER_PATTERN",
      "text": "Nunca descreva como padrão, hábito, tendência ou característica do colaborador (nada de 'costuma', 'sempre', 'frequentemente')."
    },
    {
      "code": "NO_INTENT_DIAGNOSIS",
      "text": "Não diagnostique intenção, motivação ou estado emocional do colaborador."
    },
    {
      "code": "NO_UNSUPPORTED_CAUSE",
      "text": "Não afirme causa ou consequência que a evidência não mostra."
    },
    {
      "code": "NO_INVENTED_POLICY",
      "text": "Não cite política, procedimento ou regra além do documento informado no item."
    },
    {
      "code": "NO_INVENTED_NUMBERS",
      "text": "Não escreva número, prazo, valor ou meta que não esteja na evidência ou na regra do item."
    },
    {
      "code": "NO_SYSTEM_EXECUTION_CLAIM",
      "text": "Não afirme que algo foi executado ou registrado em sistema."
    },
    {
      "code": "NO_INTERNAL_IDS",
      "text": "Não mencione identificadores, códigos ou nomes de campos."
    },
    {
      "code": "NO_AI_ATTRIBUTION",
      "text": "Não diga que uma IA, a INIA ou um sistema detectou algo."
    },
    {
      "code": "NO_DISCIPLINARY_LANGUAGE",
      "text": "Não use linguagem disciplinar (advertência, punição, penalidade, infração)."
    },
    {
      "code": "COACHING_IS_SUGGESTION",
      "text": "Em COACHING_SUGGESTION, a orientação é sugestão, nunca obrigação."
    },
    {
      "code": "NORMATIVE_ONLY_WITH_KB_RULE",
      "text": "Linguagem normativa ('deve', 'é obrigatório') só em item KB_RULE e só sobre a regra informada."
    },
    {
      "code": "PRESERVE_EVIDENCE",
      "text": "Se citar a evidência entre aspas, copie o texto exibível exatamente; nunca reconstrua dado mascarado ([CPF], [TELEFONE]…)."
    },
    {
      "code": "FILL_ONLY_WORDING",
      "text": "Preencha somente observed, whyItMatters e whatYouCanDo de cada item; nada mais."
    },
    {
      "code": "POTENTIAL_EFFECT_ONLY",
      "text": "Benefício para o cliente só como possibilidade ('pode ajudar', 'contribui para'); nunca como resultado ocorrido ou garantido ('garante que', 'assegura que', 'fez com que o cliente entendesse')."
    },
    {
      "code": "REINFORCE_OBSERVED_ONLY",
      "text": "Em ponto positivo, reforce exatamente o comportamento observado na evidência; não o troque por outro comportamento que não aparece nela."
    }
  ],
  "items": [
    {
      "itemRef": "ITEM_1",
      "section": "STRENGTH",
      "kind": "STRENGTH",
      "polarity": "POSITIVE",
      "scope": "INTERACTION_SPECIFIC",
      "safeMeaning": "comportamento positivo do operador observado nesta interação",
      "guidanceSource": "REINFORCEMENT",
      "guidanceMandatory": false,
      "knowledge": null,
      "evidence": [
        {
          "speaker": "OPERADOR",
          "text": "O prazo para a análise da contestação é de até cinco dias úteis, contando a partir de hoje.",
          "truncated": false,
          "masked": false
        }
      ],
      "evidenceWithheldCount": 0
    }
  ]
}

